<?php $titulo='Equipamentos'; $modulo='equipamentos'; ?>
<div class="mb-3"><h4 class="mb-1">Equipamentos observados</h4><p class="text-muted mb-0">Inventário coletado de leases DHCP, vizinhos de rede, sessões e acessos do Squid.</p></div><div class="card"><div class="table-responsive"><table class="table table-hover align-middle mb-0"><thead class="table-light"><tr><th>Endereço</th><th>MAC</th><th>Hostname</th><th>Grupo / política</th><th>Sessão de usuário</th><th>Origem</th><th>Requisições 24h</th><th>Download HTTP 24h</th><th>Upload HTTP 24h</th><th>Último acesso</th><th>Ações</th></tr></thead><tbody><?php foreach($equipamentos as $e):?><tr><td class="font-monospace fw-semibold"><?=h($e['ip'])?></td><td><?=h($e['mac']??'—')?></td><td><?=h($e['hostname']??'—')?></td><td><?=h($e['grupo_nome']??'Sem regra')?><?php if($e['expira_em']):?><div class="small text-warning">Regra expira <?=h($e['expira_em'])?></div><?php endif;?></td><td><?=h($e['email']??'—')?></td><td><?=h($e['origem'])?></td><td><?=number_format((int)$e['requisicoes'])?></td><td><?=formatar_bytes((int)$e['download_24h'])?></td><td><?=$e['upload_24h']===null?'sem dados':formatar_bytes((int)$e['upload_24h'])?></td><td><?=h($e['ultimo_acesso']??'—')?></td><td class="text-nowrap"><a class="btn btn-sm btn-outline-primary" href="/equipamentos/ficha?ip=<?=rawurlencode($e['ip'])?>" title="Ficha completa"><i class="bi bi-pc-display-horizontal"></i></a> <a class="btn btn-sm btn-outline-primary" href="/grupos" title="Gerenciar políticas"><i class="bi bi-shield"></i></a> <a class="btn btn-sm btn-outline-secondary" href="/internet/logs?ip=<?=rawurlencode($e['ip'])?>" title="Histórico de acesso"><i class="bi bi-clock-history"></i></a><?php if($e['email']):?> <a class="btn btn-sm btn-outline-warning" href="/internet" title="Usuários e sessões"><i class="bi bi-person-x"></i></a><?php endif;?></td></tr><?php endforeach;?><?php if(!$equipamentos):?><tr><td colspan="11" class="text-center text-muted py-4">Nenhum equipamento observado. O inventário será preenchido quando o Squid, o DHCP ou vizinhos da LAN fornecerem dados.</td></tr><?php endif;?></tbody></table></div></div>
